('SHIP03', '5100000', '2025-06-01', '2025-06-19', 1931.0000, N'Demo SHIP03 5100000 2025-06 transaction 2')
) AS v(ShipCode, AccountNumber, AccountingPeriod, TransactionDate, ActualValue, Description)
JOIN dbo.Ships s ON s.ShipCode = v.ShipCode
JOIN dbo.ChartOfAccounts a ON a.AccountNumber = v.AccountNumber
WHERE a.IsPostingAccount = 1
  AND NOT EXISTS
  (
      SELECT 1
      FROM dbo.AccountTransactions t
      WHERE t.ShipId = s.ShipId
        AND t.AccountId = a.AccountId
        AND t.AccountingPeriod = CONVERT(date, v.AccountingPeriod, 23)
        AND t.TransactionDate = CONVERT(date, v.TransactionDate, 23)
        AND t.ActualValue = v.ActualValue
        AND ISNULL(t.Description, N'') = ISNULL(v.Description, N'')
  );

COMMIT TRANSACTION;
GO
